source.exploreUrl:
@js:
url=source.getKey();
var li=url+"/wenku/#";
var html=java.ajax(li);
var h=org.jsoup.Jsoup.parse(html)
var a=h.select('div[class=sort-li-detail] a');
var list=[];
for(i in a){
	var text=a[i].text();
	var href=a[i].attr("href");
href=String(href).replace("1.html",'{{page}}.html');
	var add=text+"::"+href;
	list.push(add);
	}
list.join("&&")

