function login() {
    java.startBrowserAwait("https://www.asianfanfics.com/login", "登录 Asianfanfics");
    try {
        var home = java.ajax("https://www.asianfanfics.com/");
        if (/logout|Log out/i.test(home)) {
            java.toast("登录成功");
        } else {
            java.toast("登录可能未成功，请重试");
        }
    } catch (e) {
        java.toast("登录完成，如未成功请重试");
    }
}

