ruleContent.webJs:
(() => {
  const selector = 'div#user-submitted-body';
  if (!window.__legado_scrolled) {
    window.scrollTo(0, document.body.scrollHeight);
    window.__legado_scrolled = true;
    return null;
  }
  const el = document.querySelector(selector);
  if (!el) return null;
  const ps = el.querySelectorAll('p');
  if (ps.length === 0) return null;
  const text = el.innerText || '';
  const placeholderPattern = /couldn't be loaded|Refresh the page|请稍候/i;
  if (placeholderPattern.test(text) && ps.length < 3) return null;
  return el.innerHTML;
})();

